(7692988, 1260893, 143116, '<td valign="top">Did you try to make the sun "smaller"? It might have enhanced the effect, I think.</td>', 'Did you try to make the sun "smaller"? It might have enhanced the effect, I think.', '2021-04-30 10:08:14.000000', NULL, 1),
(7692989, 1260758, 143116, '<td valign="top">Did you use a starlight filter for this effect?</td>', 'Did you use a starlight filter for this effect?', '2021-04-30 10:09:51.000000', NULL, 1),
(7692990, 1261022, 143116, '<td valign="top">Nice effort, and I like how your face is lit. But in terms of starlights you should have used (a) much smaller light source(s), I think.</td>', 'Nice effort, and I like how your face is lit. But in terms of starlights you should have used (a) much smaller light source(s), I think.', '2021-04-30 10:11:15.000000', NULL, 1),
(7692991, 1261009, 143116, '<td valign="top">The starburst looks a bit scruffy. I think you could have gotten s sharper starburst by covering some more of the sun.</td>', 'The starburst looks a bit scruffy. I think you could have gotten s sharper starburst by covering some more of the sun.', '2021-04-30 10:14:44.000000', NULL, 1),
(7692992, 1260995, 143116, '<td valign="top">You dare, shooting straight into the sun! In my (very limited) experience you can get a better starburst effect if you make your light source smaller, i.e. cover (most of) the sun.</td>', 'You dare, shooting straight into the sun! In my (very limited) experience you can get a better starburst effect if you make your light source smaller, i.e. cover (most of) the sun.', '2021-04-30 10:16:19.000000', NULL, 1),
