(7693231, 1261008, 3306, '<td valign="top">I like the way you captured the sun directly in the middle of the trees and a very good starburst pattern. Top 3.</td>', 'I like the way you captured the sun directly in the middle of the trees and a very good starburst pattern. Top 3.', '2021-05-02 22:53:37.000000', NULL, 1),
(7693232, 1260784, 173844, '<td valign="top">Except for that lower bottom one, the starbursts are understated, which I appreciate.  The entirety of the image is intricate and enjoyable to explore.  The variety of shapes and lines, then, is engaging while avoiding being cacophanous.  So suitable for a black and white treatment.<br/>Personal favorite of the challenge.</td>', 'Except for that lower bottom one, the starbursts are understated, which I appreciate.  The entirety of the image is intricate and enjoyable to explore.  The variety of shapes and lines, then, is engaging while avoiding being cacophanous.  So suitable for a black and white treatment.Personal favorite of the challenge.', '2021-05-02 22:54:11.000000', NULL, 1),
(7693233, 1261018, 3306, '<td valign="top">Awesome shot. Well seen. One of my favorites.</td>', 'Awesome shot. Well seen. One of my favorites.', '2021-05-02 22:54:15.000000', NULL, 1),
(7693234, 1261004, 3306, '<td valign="top">Well done! Congrats.</td>', 'Well done! Congrats.', '2021-05-02 22:54:52.000000', NULL, 1),
